1	/**
2	 * Extracts `@handle` mentions from comment bodies and resolves them to member
3	 * ids.
4	 *
5	 * A handle is the local part of a member's email address, lowercased — that
6	 * is what the comment composer autocompletes and what `CommentService` feeds
7	 * to the notification fan-out, so extraction and resolution must agree
8	 * exactly. Mentions inside code spans and fenced blocks are ignored.
9	 */
10	import type { UserId } from "@/types/common";
11	import type { MemberWithUser } from "@/types/member";
12	
13	/** `@` must start the line or follow whitespace/punctuation, never an email. */
14	const MENTION_PATTERN = /(^|[\s(<[])@([a-z0-9][a-z0-9._-]{0,38}[a-z0-9])/gi;
15	
16	function withoutCode(body: string): string {
17	  return body.replace(/```[\s\S]*?```/g, " ").replace(/`[^`]*`/g, " ");
18	}
19	
20	/** The handle Taskflow addresses a member by, derived from their email. */
21	export function handleOf(member: MemberWithUser): string {
22	  return (member.user.email.split("@")[0] ?? "").toLowerCase();
23	}
24	
25	/** Every distinct handle mentioned, in first-appearance order. */
26	export function extractMentions(body: string): readonly string[] {
27	  const seen = new Set<string>();
28	  const handles: string[] = [];
29	
30	  for (const match of withoutCode(body).matchAll(MENTION_PATTERN)) {
31	    const handle = (match[2] ?? "").toLowerCase();
32	    if (handle === "" || seen.has(handle)) continue;
33	    seen.add(handle);
34	    handles.push(handle);
35	  }
36	
37	  return handles;
38	}
39	
40	/**
41	 * Maps the mentions in `body` onto the ids of members who actually exist in
42	 * the organization. Unknown handles are silently dropped — a typo must never
43	 * fail the comment write.
44	 */
