/** An assignee must be a live member of the org the issue is being assigned in. */
async function assertAssignableMember(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  requireFound(await memberRepo.findMember(orgId, userId), "Member", userId);
}

/**
 * A parent must be a live issue of the *same project* — a parent from another
 * project, another org, or an archived issue is refused as not found rather
 * than exposed.
 */
async function assertLiveParentInProject(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<void> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  const validParent =
    parent !== null && parent.projectId === projectId && !isArchived(parent);
  requireFound(validParent ? parent : null, "Issue", parentId);
}

/** Every label id must be one of the org's own labels. */
async function assertOwnLabels(
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;
  const own = new Set((await labelRepo.listLabels(orgId)).map((l) => l.id));
  for (const labelId of labelIds) {
    requireFound(own.has(labelId) ? labelId : null, "Label", labelId);
  }
}

